CREATE OR REPLACE FUNCTION public.nwtb_add_delivery_driver(p_employee_number text, p_display_name text, p_created_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_name text:=btrim(coalesce(p_display_name,''));v_driver text:=btrim(coalesce(p_employee_number,''));v_existing public.employees%ROWTYPE;
BEGIN
 IF v_driver !~ '^[0-9]{4}$' OR v_driver='9998' OR length(v_name)<2 OR length(v_name)>120 THEN RAISE EXCEPTION 'A name and a valid 4-digit employee number are required.' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.employees WHERE employee_number=p_created_by AND active) THEN RAISE EXCEPTION 'Office employee is not active.' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.nwtb_system_control WHERE id=1 AND state<>'KILLED' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'NWTB Delivery System is locked.' USING ERRCODE='P0001'; END IF;
 SELECT * INTO v_existing FROM public.employees WHERE employee_number=v_driver FOR UPDATE;
 IF FOUND THEN
  IF v_existing.active AND v_existing.display_name=v_name AND EXISTS(SELECT 1 FROM public.nwtb_delivery_roles WHERE employee_number=v_driver AND role='DRIVER' AND active) THEN
   RETURN jsonb_build_object('employee_number',v_driver,'display_name',v_name,'role','DRIVER','active',true,'already_exists',true);
  END IF;
  RAISE EXCEPTION 'Employee number already exists. Use USER ROLES to manage the existing employee.' USING ERRCODE='23505';
 END IF;
 INSERT INTO public.employees(employee_number,display_name,active) VALUES(v_driver,v_name,true);
 INSERT INTO public.nwtb_delivery_roles(employee_number,role,active,updated_at,updated_by) VALUES(v_driver,'DRIVER',true,now(),p_created_by)
 ON CONFLICT(employee_number) DO UPDATE SET role='DRIVER',active=true,updated_at=excluded.updated_at,updated_by=excluded.updated_by;
 INSERT INTO public.delivery_events(employee_number,event_type,note) VALUES(p_created_by,'DELIVERY_DRIVER_ADDED',format('Driver added: %s (%s)',v_name,v_driver));
 RETURN jsonb_build_object('employee_number',v_driver,'display_name',v_name,'role','DRIVER','active',true,'already_exists',false);
END;$function$

CREATE OR REPLACE FUNCTION public.nwtb_commit_multi_routes(p_created_by text, p_route_date date, p_routes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r jsonb;
  s jsonb;
  v_driver text;
  v_depot text;
  v_order uuid;
  v_route uuid;
  v_seq integer;
  v_seen uuid[] := array[]::uuid[];
  v_result jsonb := '[]'::jsonb;
  v_start_name text;
  v_start_address text;
  v_start_lat double precision;
  v_start_lon double precision;
begin
  if p_routes is null or jsonb_typeof(p_routes) <> 'array' or jsonb_array_length(p_routes)=0 then
    raise exception 'At least one driver route is required.';
  end if;

  -- Validate the entire route set before writing anything.
  -- IMPORTANT: a driver may already have ACTIVE or PLANNED routes.
  -- Office pre-routing is allowed. Only route start enforces one ACTIVE route at a time.
  for r in select value from jsonb_array_elements(p_routes)
  loop
    v_driver := trim(coalesce(r->>'driver_employee_number',''));
    v_depot := upper(trim(coalesce(r->>'depot','')));

    if v_driver !~ '^\d{4}$' then
      raise exception 'Every route requires a valid 4-digit driver employee number.';
    end if;

    if v_depot not in ('BOLINGBROOK','PALATINE') then
      raise exception 'Every driver requires a valid depot.';
    end if;

    if not exists (
      select 1
      from public.employees e
      join public.nwtb_delivery_roles dr on dr.employee_number=e.employee_number
      where e.employee_number=v_driver
        and e.active=true
        and dr.active=true
        and dr.role='DRIVER'
    ) then
      raise exception 'Driver % is not an active NWTB driver.', v_driver;
    end if;

    if jsonb_typeof(r->'stops') <> 'array' or jsonb_array_length(r->'stops')=0 then
      raise exception 'Every selected driver must receive at least one stop.';
    end if;

    for s in select value from jsonb_array_elements(r->'stops')
    loop
      begin
        v_order := (s->>'order_id')::uuid;
      exception when others then
        raise exception 'A route contains an invalid stop identifier.';
      end;

      if v_order = any(v_seen) then
        raise exception 'The same delivery stop was assigned more than once.';
      end if;

      if not exists (
        select 1 from public.delivery_orders
        where id=v_order and status='UNASSIGNED'
      ) then
        raise exception 'One or more selected stops are no longer AVAILABLE.';
      end if;

      v_seen := array_append(v_seen,v_order);
    end loop;
  end loop;

  -- Every validation passed. Create all routes in one transaction.
  for r in select value from jsonb_array_elements(p_routes)
  loop
    v_driver := trim(r->>'driver_employee_number');
    v_depot := upper(trim(r->>'depot'));

    if v_depot='PALATINE' then
      v_start_name := 'Northwest Trucks - Palatine';
      v_start_address := '2120 N Rand Rd, Palatine, IL 60074';
      v_start_lat := 42.148326;
      v_start_lon := -88.033080;
    else
      v_start_name := 'Northwest Trucks - Bolingbrook';
      v_start_address := '201 S W Frontage Rd, Bolingbrook, IL 60440';
      v_start_lat := 41.682487;
      v_start_lon := -88.072262;
    end if;

    insert into public.delivery_routes(
      route_date,depot,driver_employee_number,wave,status,
      estimated_miles,estimated_minutes,created_by,route_note,route_mode,
      start_name,start_address,start_lat,start_lon,
      end_mode,end_name,end_address,end_lat,end_lon,
      drive_minutes,service_minutes,return_miles,return_minutes,
      traffic_aware,matrix_source
    ) values (
      coalesce(p_route_date,current_date),
      v_depot,
      v_driver,
      'CUSTOM',
      'PLANNED',
      nullif(r->>'estimated_miles','')::numeric,
      nullif(r->>'estimated_minutes','')::integer,
      p_created_by,
      'Automatic multi-driver pre-route; starts and returns to '||v_depot||'.',
      'MULTI_DRIVER_OPTIMIZED',
      v_start_name,v_start_address,v_start_lat,v_start_lon,
      'RETURN_DEPOT',v_start_name,v_start_address,v_start_lat,v_start_lon,
      nullif(r->>'drive_minutes','')::integer,
      nullif(r->>'service_minutes','')::integer,
      nullif(r->>'return_miles','')::numeric,
      nullif(r->>'return_minutes','')::integer,
      coalesce((r->>'traffic_aware')::boolean,false),
      nullif(r->>'matrix_source','')
    )
    returning id into v_route;

    v_seq := 0;
    for s in
      select value
      from jsonb_array_elements(r->'stops')
      order by (value->>'stop_sequence')::integer
    loop
      v_seq := v_seq + 1;
      v_order := (s->>'order_id')::uuid;

      insert into public.delivery_route_stops(
        route_id,order_id,stop_sequence,status
      ) values (
        v_route,v_order,v_seq,'PENDING'
      );

      update public.delivery_orders
      set status='ROUTED',last_status_at=now(),updated_at=now()
      where id=v_order and status='UNASSIGNED';

      if not found then
        raise exception 'A selected stop changed while routes were being created.';
      end if;
    end loop;

    insert into public.delivery_events(
      route_id,employee_number,event_type,note
    ) values (
      v_route,p_created_by,'ROUTE_CREATED',
      'Office pre-route created: '||v_seq||' stop(s), depot '||v_depot
    );

    v_result := v_result || jsonb_build_array(
      jsonb_build_object(
        'route_id',v_route,
        'driver_employee_number',v_driver,
        'depot',v_depot,
        'stop_count',v_seq,
        'estimated_miles',nullif(r->>'estimated_miles','')::numeric,
        'estimated_minutes',nullif(r->>'estimated_minutes','')::integer,
        'drive_minutes',nullif(r->>'drive_minutes','')::integer,
        'service_minutes',nullif(r->>'service_minutes','')::integer,
        'return_miles',nullif(r->>'return_miles','')::numeric,
        'return_minutes',nullif(r->>'return_minutes','')::integer
      )
    );
  end loop;

  return jsonb_build_object('ok',true,'routes',v_result);
end;
$function$

CREATE OR REPLACE FUNCTION public.nwtb_confirm_route_return(p_route_id uuid, p_driver_employee_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE r public.delivery_routes; n bigint; all_done boolean; t timestamptz:=now();
BEGIN
 IF EXISTS(SELECT 1 FROM public.nwtb_system_control WHERE id=1 AND state='KILLED') THEN RAISE EXCEPTION 'NWTB_SYSTEM_KILLED'; END IF;
 SELECT * INTO r FROM public.delivery_routes WHERE id=p_route_id FOR UPDATE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'Route not found.'; END IF;
 IF r.driver_employee_number IS DISTINCT FROM p_driver_employee_number THEN RAISE EXCEPTION 'Route is assigned to another driver.'; END IF;
 IF r.status='COMPLETED' AND r.returned_at IS NOT NULL THEN
  RETURN jsonb_build_object('route_id',r.id,'route_status','COMPLETED','returned_at',r.returned_at,'already_confirmed',true);
 END IF;
 IF r.status<>'ACTIVE' OR r.released_to_driver IS DISTINCT FROM true THEN RAISE EXCEPTION 'Only a released ACTIVE route can confirm its return.'; END IF;
 IF NOT public.nwtb_route_needs_return(to_jsonb(r)) THEN RAISE EXCEPTION 'This route ends at its last stop.'; END IF;
 IF r.paused_at IS NOT NULL AND (r.resumed_at IS NULL OR r.paused_at>r.resumed_at) THEN RAISE EXCEPTION 'Resume the route before confirming arrival.'; END IF;
 SELECT count(*),coalesce(bool_and(coalesce(status IN ('DELIVERED','NOT_DELIVERED','SKIPPED'),false)),false)
 INTO n,all_done FROM public.delivery_route_stops WHERE route_id=r.id;
 IF n=0 OR NOT all_done THEN RAISE EXCEPTION 'Finish all assigned stops before confirming the return.'; END IF;
 IF r.returning_started_at IS NULL THEN PERFORM public.nwtb_finish_route_stops(r.id,p_driver_employee_number); END IF;
 UPDATE public.delivery_routes SET status='COMPLETED',returned_at=t,updated_at=t WHERE id=r.id;
 INSERT INTO public.delivery_events(route_id,employee_number,event_type,note)
 VALUES(r.id,p_driver_employee_number,'ROUTE_RETURNED','Driver explicitly confirmed arrival at the assigned return location.'),
       (r.id,p_driver_employee_number,'ROUTE_COMPLETED','Route completed after driver confirmed the return leg.');
 RETURN jsonb_build_object('route_id',r.id,'route_status','COMPLETED','returned_at',t,'already_confirmed',false);
END $function$

CREATE OR REPLACE FUNCTION public.nwtb_create_restore_point(p_label text, p_reason text DEFAULT NULL::text, p_kind text DEFAULT 'MANUAL'::text, p_created_by text DEFAULT 'SYSTEM'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_id uuid;
  v_count bigint;
  v_counts jsonb := '{}'::jsonb;
  v_kind text := upper(coalesce(p_kind,'MANUAL'));
begin
  if v_kind not in ('DAILY','MANUAL','PRE_DEPLOY','INITIAL') then raise exception 'Invalid restore point kind'; end if;
  insert into public.nwtb_restore_points(label,reason,kind,status,created_by)
  values(left(coalesce(nullif(trim(p_label),''),'NWTB Restore Point'),200),left(nullif(trim(p_reason),''),1000),v_kind,'CREATING',left(coalesce(nullif(trim(p_created_by),''),'SYSTEM'),120))
  returning id into v_id;
  insert into public.nwtb_restore_point_rows select v_id,'delivery_routes',t.id::text,to_jsonb(t) from public.delivery_routes t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_routes',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_route_stops',t.id::text,to_jsonb(t) from public.delivery_route_stops t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_route_stops',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_orders',t.id::text,to_jsonb(t) from public.delivery_orders t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_orders',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_saved_locations',t.id::text,to_jsonb(t) from public.delivery_saved_locations t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_saved_locations',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_master_versions',t.kind::text,to_jsonb(t) from public.delivery_master_versions t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_master_versions',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'employees',t.employee_number::text,to_jsonb(t) from public.employees t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('employees',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_tracking_devices',t.id::text,to_jsonb(t) from public.delivery_tracking_devices t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_tracking_devices',v_count);
  insert into public.nwtb_restore_point_rows select v_id,'delivery_pods',t.id::text,to_jsonb(t) from public.delivery_pods t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_pods',v_count);
  if v_kind in ('MANUAL','PRE_DEPLOY','INITIAL') then
    insert into public.nwtb_restore_point_rows select v_id,'delivery_chat_messages',t.id::text,to_jsonb(t) from public.delivery_chat_messages t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_chat_messages',v_count);
    insert into public.nwtb_restore_point_rows select v_id,'delivery_events',t.id::text,to_jsonb(t) from public.delivery_events t; get diagnostics v_count=row_count; v_counts:=v_counts||jsonb_build_object('delivery_events',v_count);
  end if;
  update public.nwtb_restore_points set status='COMPLETE',completed_at=now(),row_counts=v_counts where id=v_id;
  return v_id;
exception when others then
  if v_id is not null then update public.nwtb_restore_points set status='FAILED',completed_at=now(),reason=left(coalesce(reason,'')||case when reason is null or reason='' then '' else ' | ' end||'Checkpoint error: '||sqlerrm,1000) where id=v_id; end if;
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.nwtb_enforce_delivery_route_driver_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_role text;
  v_active boolean;
begin
  select role,active into v_role,v_active
  from public.nwtb_delivery_roles
  where employee_number=new.driver_employee_number;

  if v_role is distinct from 'DRIVER' or v_active is distinct from true then
    raise exception 'Assigned employee is not an active NWTB Delivery DRIVER';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.nwtb_finalize_pod(p_pod_id uuid, p_stop_id uuid, p_driver_employee_number text, p_driver_display_name text, p_recipient_name text, p_notes text, p_lat double precision, p_lon double precision, p_accuracy_m double precision, p_captured_at timestamp with time zone, p_signature_path text, p_signature_sha256 text, p_photo_path text, p_photo_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_route_id uuid;
  v_order_id uuid;
  v_stop_status text;
  v_route_driver text;
  v_driver_role text;
  v_driver_role_active boolean;
  v_customer_name text;
  v_pod_number bigint;
  v_remaining bigint;
  v_route_completed boolean := false;
  v_route_status text;
  v_released boolean;
  v_paused_at timestamptz;
  v_resumed_at timestamptz;
  v_finish jsonb;
  v_state text;
begin
  select state into v_state from public.nwtb_system_control where id=1;
  if v_state='KILLED' then raise exception 'NWTB_SYSTEM_KILLED'; end if;

  select role,active into v_driver_role,v_driver_role_active
  from public.nwtb_delivery_roles
  where employee_number=p_driver_employee_number;
  if v_driver_role is distinct from 'DRIVER' or v_driver_role_active is distinct from true then
    raise exception 'Driver is not an active NWTB Delivery DRIVER';
  end if;

  -- Serialize stop completion and return confirmation on the route row first.
  select route_id into v_route_id from public.delivery_route_stops where id=p_stop_id;
  perform 1 from public.delivery_routes where id=v_route_id for update;
  select s.route_id,s.order_id,s.status,r.driver_employee_number,o.customer_name,r.status,r.released_to_driver,r.paused_at,r.resumed_at
    into v_route_id,v_order_id,v_stop_status,v_route_driver,v_customer_name,v_route_status,v_released,v_paused_at,v_resumed_at
  from public.delivery_route_stops s
  join public.delivery_routes r on r.id=s.route_id
  join public.delivery_orders o on o.id=s.order_id
  where s.id=p_stop_id
  for update of s;

  if v_route_id is null then raise exception 'Stop not found'; end if;
  if v_route_driver is distinct from p_driver_employee_number then raise exception 'Stop is assigned to another driver'; end if;
  if v_route_status is distinct from 'ACTIVE' or v_released is distinct from true then raise exception 'Start a released route before completing a stop'; end if;
  if v_paused_at is not null and (v_resumed_at is null or v_paused_at>v_resumed_at) then raise exception 'Resume the route before completing a stop'; end if;
  if v_stop_status is distinct from 'PENDING' then raise exception 'Stop is no longer pending'; end if;
  if nullif(trim(p_recipient_name),'') is null then raise exception 'Recipient name is required'; end if;
  if p_signature_path is null and p_photo_path is null then raise exception 'Signature or photo is required'; end if;

  insert into public.delivery_pods(
    id,route_id,stop_id,order_id,driver_employee_number,driver_display_name,
    recipient_name,delivery_result,notes,lat,lon,accuracy_m,captured_at,
    signature_path,signature_sha256,photo_path,photo_sha256
  ) values (
    p_pod_id,v_route_id,p_stop_id,v_order_id,p_driver_employee_number,left(p_driver_display_name,180),
    left(trim(p_recipient_name),180),'DELIVERED',left(nullif(trim(p_notes),''),1500),
    p_lat,p_lon,p_accuracy_m,coalesce(p_captured_at,now()),
    p_signature_path,p_signature_sha256,p_photo_path,p_photo_sha256
  ) returning pod_number into v_pod_number;

  update public.delivery_route_stops
     set status='DELIVERED',completed_at=coalesce(p_captured_at,now()),driver_note=left(nullif(trim(p_notes),''),1000),updated_at=now()
   where id=p_stop_id;

  update public.delivery_orders
     set status='DELIVERED',last_status_at=coalesce(p_captured_at,now()),updated_at=now()
   where id=v_order_id;

  insert into public.delivery_events(route_id,stop_id,order_id,employee_number,event_type,note)
  values(v_route_id,p_stop_id,v_order_id,p_driver_employee_number,'POD_CAPTURED',
         'POD #'||v_pod_number||' captured for '||coalesce(v_customer_name,'delivery')||'; received by '||left(trim(p_recipient_name),180));

  insert into public.delivery_events(route_id,stop_id,order_id,employee_number,event_type,note)
  values(v_route_id,p_stop_id,v_order_id,p_driver_employee_number,'STOP_DELIVERED','Delivered with POD #'||v_pod_number);

  select count(*) into v_remaining
  from public.delivery_route_stops
  where route_id=v_route_id and status='PENDING';

  if v_remaining=0 then
    v_finish:=public.nwtb_finish_route_stops(v_route_id,p_driver_employee_number);
    v_route_completed:=coalesce((v_finish->>'route_completed')::boolean,false);
  end if;

  return jsonb_build_object(
    'pod_id',p_pod_id,
    'pod_number',v_pod_number,
    'route_id',v_route_id,
    'stop_id',p_stop_id,
    'order_id',v_order_id,
    'route_completed',v_route_completed,
    'return_pending',coalesce((v_finish->>'return_pending')::boolean,false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.nwtb_finish_route_stops(p_route_id uuid, p_driver_employee_number text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE r public.delivery_routes; n bigint; all_done boolean; started timestamptz; t timestamptz:=now();
BEGIN
 IF EXISTS(SELECT 1 FROM public.nwtb_system_control WHERE id=1 AND state='KILLED') THEN RAISE EXCEPTION 'NWTB_SYSTEM_KILLED'; END IF;
 SELECT * INTO r FROM public.delivery_routes WHERE id=p_route_id FOR UPDATE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'Route not found.'; END IF;
 IF r.driver_employee_number IS DISTINCT FROM p_driver_employee_number THEN RAISE EXCEPTION 'Route is assigned to another driver.'; END IF;
 IF r.status='COMPLETED' AND (r.returned_at IS NOT NULL OR NOT public.nwtb_route_needs_return(to_jsonb(r))) THEN
  RETURN jsonb_build_object('route_id',r.id,'route_status','COMPLETED','route_completed',true,'return_pending',false);
 END IF;
 IF r.status <> 'ACTIVE' OR r.released_to_driver IS DISTINCT FROM true THEN RAISE EXCEPTION 'Only a released ACTIVE route can finish stops.'; END IF;
 IF r.paused_at IS NOT NULL AND (r.resumed_at IS NULL OR r.paused_at>r.resumed_at) THEN RAISE EXCEPTION 'Resume the route before finishing stops.'; END IF;
 SELECT count(*),coalesce(bool_and(coalesce(status IN ('DELIVERED','NOT_DELIVERED','SKIPPED'),false)),false)
 INTO n,all_done FROM public.delivery_route_stops WHERE route_id=r.id;
 IF n=0 OR NOT all_done THEN
  RETURN jsonb_build_object('route_id',r.id,'route_status','ACTIVE','route_completed',false,'return_pending',false);
 END IF;
 IF public.nwtb_route_needs_return(to_jsonb(r)) THEN
  started:=coalesce(r.returning_started_at,t);
  IF r.returning_started_at IS NULL THEN
   UPDATE public.delivery_routes SET returning_started_at=started,returned_at=NULL,updated_at=t WHERE id=r.id;
   INSERT INTO public.delivery_events(route_id,employee_number,event_type,note)
   VALUES(r.id,p_driver_employee_number,'ROUTE_RETURNING','All stops finished. Assigned return leg is in progress; driver arrival is not yet confirmed.');
  END IF;
  RETURN jsonb_build_object('route_id',r.id,'route_status','ACTIVE','route_completed',false,'return_pending',true,'returning_started_at',started);
 END IF;
 UPDATE public.delivery_routes SET status='COMPLETED',updated_at=t WHERE id=r.id;
 INSERT INTO public.delivery_events(route_id,employee_number,event_type,note)
 VALUES(r.id,p_driver_employee_number,'ROUTE_COMPLETED','All stops finished. This route ends at its last stop.');
 RETURN jsonb_build_object('route_id',r.id,'route_status','COMPLETED','route_completed',true,'return_pending',false);
END $function$

CREATE OR REPLACE FUNCTION public.nwtb_keep_return_leg_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE n bigint; all_done boolean;
BEGIN
 IF OLD.status='ACTIVE' AND NEW.status='COMPLETED' AND NEW.returned_at IS NULL
    AND public.nwtb_route_needs_return(to_jsonb(NEW)) THEN
  SELECT count(*),coalesce(bool_and(coalesce(status IN ('DELIVERED','NOT_DELIVERED','SKIPPED'),false)),false)
   INTO n,all_done FROM public.delivery_route_stops WHERE route_id=NEW.id;
  IF n=0 OR NOT all_done THEN RAISE EXCEPTION 'Cannot complete a route with unfinished stops.'; END IF;
  NEW.status:='ACTIVE';NEW.returning_started_at:=coalesce(NEW.returning_started_at,now());
  IF OLD.returning_started_at IS NULL THEN
   INSERT INTO public.delivery_events(route_id,employee_number,event_type,note)
   VALUES(NEW.id,NEW.driver_employee_number,'ROUTE_RETURNING','All stops finished. Return leg remains ACTIVE until driver confirms arrival.');
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nwtb_pending_stop_reopens_return()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE r public.delivery_routes;
BEGIN
 IF NEW.status='PENDING' THEN
  SELECT * INTO r FROM public.delivery_routes WHERE id=NEW.route_id FOR UPDATE;
  IF r.id IS NULL OR r.status NOT IN ('PLANNED','ACTIVE') THEN RAISE EXCEPTION 'Only a planned or active route can receive a pending stop.'; END IF;
  IF r.returning_started_at IS NOT NULL OR r.returned_at IS NOT NULL THEN
   UPDATE public.delivery_routes SET returning_started_at=NULL,returned_at=NULL,updated_at=now() WHERE id=r.id;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nwtb_resolve_delivery_exception(p_exception_id uuid, p_action text, p_employee_number text, p_resolution_note text DEFAULT NULL::text)
 RETURNS delivery_exceptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ex public.delivery_exceptions;
  v_name text;
  v_t timestamptz := now();
begin
  select * into v_ex from public.delivery_exceptions where id=p_exception_id for update;
  if v_ex.id is null then raise exception 'Exception not found.'; end if;
  if v_ex.status <> 'OPEN' then raise exception 'This exception is already resolved.'; end if;
  if p_action not in ('RETRY_AVAILABLE','CLOSE_NO_RETRY') then raise exception 'Invalid exception resolution.'; end if;
  select display_name into v_name from public.employees where employee_number=p_employee_number;

  if p_action='RETRY_AVAILABLE' then
    insert into public.delivery_events(route_id,order_id,employee_number,event_type,note)
      values(v_ex.route_id,v_ex.order_id,p_employee_number,'EXCEPTION_RETURNED_AVAILABLE',concat('Exception #',v_ex.exception_number,' returned to AVAILABLE for retry.',case when nullif(trim(coalesce(p_resolution_note,'')),'') is not null then ' '||trim(p_resolution_note) else '' end));
    delete from public.delivery_route_stops where id=v_ex.stop_id and status='NOT_DELIVERED';
    update public.delivery_orders set status='UNASSIGNED',last_status_at=v_t,updated_at=v_t where id=v_ex.order_id;
  else
    insert into public.delivery_events(route_id,order_id,employee_number,event_type,note)
      values(v_ex.route_id,v_ex.order_id,p_employee_number,'EXCEPTION_CLOSED_NO_RETRY',concat('Exception #',v_ex.exception_number,' closed with no retry.',case when nullif(trim(coalesce(p_resolution_note,'')),'') is not null then ' '||trim(p_resolution_note) else '' end));
  end if;

  update public.delivery_exceptions
    set status='RESOLVED',resolution_action=p_action,resolution_note=nullif(trim(coalesce(p_resolution_note,'')),''),resolved_by_employee_number=p_employee_number,resolved_by_display_name=v_name,resolved_at=v_t,updated_at=v_t
    where id=p_exception_id
    returning * into v_ex;
  return v_ex;
end;
$function$

CREATE OR REPLACE FUNCTION public.nwtb_snapshot_delivery_exceptions_on_restore_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer;
begin
  if new.status='COMPLETE' and old.status is distinct from new.status then
    insert into public.nwtb_restore_point_rows(restore_point_id,table_name,row_key,row_data)
    select new.id,'delivery_exceptions',e.id::text,to_jsonb(e)
    from public.delivery_exceptions e
    on conflict (restore_point_id,table_name,row_key) do update set row_data=excluded.row_data;
    select count(*) into v_count from public.delivery_exceptions;
    update public.nwtb_restore_points
      set row_counts=coalesce(row_counts,'{}'::jsonb)||jsonb_build_object('delivery_exceptions',v_count)
      where id=new.id;
  end if;
  return new;
end;
$function$

